mapper.select:
SELECT COUNT(*)
FROM transactions
WHERE wallet_id = #{walletId}
  AND type = 'TRANSFER_OUT'
  AND created_at >= #{since}
  AND transaction_id <> #{excludedTransactionId}

SELECT COUNT(DISTINCT recipient_id)
FROM transactions
WHERE wallet_id = #{walletId}
  AND type = 'TRANSFER_OUT'
  AND created_at >= #{since}
  AND transaction_id <> #{excludedTransactionId}

SELECT bank_code, account_no, send_count, is_registered_safe, safe_registered_by
FROM recipients
WHERE recipient_id = #{recipientId}
